insert into quiz_questions (id, quiz_id, question_text, type, timer_seconds, marks, explanation, display_order) values ('03aafd1e-b4f3-47a9-a0e0-620e8b9dfe8e', 'bceab626-87a7-4f2a-86f6-0e937baef40d', 'Tulip Crimson – B-2103 , Area: 3,090 Sq.Ft. , IM Login BSP: 12,690/sq.ft. , PLC: 750/sq.ft. ,IM Login Rate Incl PLC: 13,440/sq.ft. Other Charges: 27,00,000 ,Selling Price Incl PLC: 15,000/sq.ft. - A customer asks, "What is the actual premium per sq.ft. on this inventory?"', 'mcq', 120, 1, 'Calculation:  Selling Rate Incl PLC = 15,000  IM Login Rate Incl PLC = 13,440  Premium =  15,000 − 13,440  = 1,560/sq.ft.', 14);
