insert into quiz_questions (id, quiz_id, question_text, type, timer_seconds, marks, explanation, display_order) values ('4133531c-2196-407d-b8b1-de2075c78174', 'bceab626-87a7-4f2a-86f6-0e937baef40d', 'Tulip Monsella – T4-3202 , Type: 3 BHK, Area: 2,874 Sq.Ft., Other Charges: 37,00,000, Book Value: 30,550/sq.ft., Selling Price: ₹35,000/sq.ft. : The owner claims he is earning a premium of 4,450 per sq.ft. Is he correct?', 'mcq', 120, 1, 'Premium per sq.ft. based on BSP:  35,000 − 30,550  = 4,450/sq.ft.', 16);
